# 推斷：資料表=用料明細（表頭第1-2列）｜欄位=項次、料號、品名、尺寸｜篩選=尺寸≠Ok｜輸出=新工作表「尺寸不合格」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb["用料明細"]

# 找出表頭列：主欄位列與檢驗項目子欄位列
header_row_main = None
header_row_sub = None
for r in range(1, min(ws.max_row, 5) + 1):
    for c in range(1, ws.max_column + 1):
        val = ws.cell(row=r, column=c).value
        if val == "項次":
            header_row_main = r
        if val == "尺寸":
            header_row_sub = r

if header_row_main is None or header_row_sub is None:
    raise ValueError("無法定位表頭（項次/尺寸）")

# 建立欄名→欄號對照
col_map = {}
# 主欄位使用主表頭列
for c in range(1, ws.max_column + 1):
    val = ws.cell(row=header_row_main, column=c).value
    if val:
        col_map[val] = c
# 檢驗項目子欄位使用子表頭列（覆蓋 E~G）
for c in range(1, ws.max_column + 1):
    val = ws.cell(row=header_row_sub, column=c).value
    if val:
        col_map[val] = c

required = ["項次", "料號", "品名", "尺寸"]
for f in required:
    if f not in col_map:
        raise ValueError(f"缺少欄位：{f}")

data_start = max(header_row_main, header_row_sub) + 1
bad_rows = []
for r in range(data_start, ws.max_row + 1):
    size_val = ws.cell(row=r, column=col_map["尺寸"]).value
    if size_val is None:
        size_val = ""
    if str(size_val).strip() != "Ok":
        bad_rows.append([
            ws.cell(row=r, column=col_map["項次"]).value,
            ws.cell(row=r, column=col_map["料號"]).value,
            ws.cell(row=r, column=col_map["品名"]).value,
            ws.cell(row=r, column=col_map["尺寸"]).value,
        ])

new_sheet_name = "尺寸不合格"
if new_sheet_name in wb.sheetnames:
    del wb[new_sheet_name]
new_ws = wb.create_sheet(title=new_sheet_name)

new_ws.append(required)
for row in bad_rows:
    new_ws.append(row)

wb.save(OUTPUT_PATH)
```

