# 推斷：資料表=主件表（表頭跨第1-2列）｜欄位=項次、料號、品名、包裝｜主檔=主件表｜鍵=包裝｜篩選=包裝值不等於"Ok"｜輸出=新工作表"包裝異常"
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb["主件表"]

# 建立兩層表頭的有效欄名對照：
# 第1列為主標頭，若該欄屬於合併群組（如 E1:G1 的「品保確認」），則取第2列的子標頭
header_row1 = [ws.cell(row=1, column=c).value for c in range(1, ws.max_column + 1)]
header_row2 = [ws.cell(row=2, column=c).value for c in range(1, ws.max_column + 1)]

merged_cols = set()
for merged_range in ws.merged_cells.ranges:
    if merged_range.min_row == 1:
        for col in range(merged_range.min_col, merged_range.max_col + 1):
            merged_cols.add(col)

col_map = {}
for idx, (h1, h2) in enumerate(zip(header_row1, header_row2), start=1):
    if idx in merged_cols and h2 is not None:
        col_map[h2] = idx
    elif h1 is not None:
        col_map[h1] = idx

# 需要的輸出欄位
required_cols = ["項次", "料號", "品名", "包裝"]
col_indices = [col_map[c] for c in required_cols]

# 篩選「包裝」不是 "Ok" 的資料列（資料自第3列起）
filtered_rows = []
for row in range(3, ws.max_row + 1):
    packaging = ws.cell(row=row, column=col_map["包裝"]).value
    if packaging is not None and packaging != "Ok":
        filtered_rows.append([ws.cell(row=row, column=ci).value for ci in col_indices])

# 建立新工作表
new_sheet_name = "包裝異常"
if new_sheet_name in wb.sheetnames:
    wb.remove(wb[new_sheet_name])
new_ws = wb.create_sheet(title=new_sheet_name)

# 寫入標題列
for c_idx, col_name in enumerate(required_cols, start=1):
    new_ws.cell(row=1, column=c_idx, value=col_name)

# 寫入篩選後資料
for r_idx, row_data in enumerate(filtered_rows, start=2):
    for c_idx, value in enumerate(row_data, start=1):
        new_ws.cell(row=r_idx, column=c_idx, value=value)

wb.save(OUTPUT_PATH)
