```python
# 推斷：資料表=零件清單（表頭第 1 列）｜欄位=項次 (A), M/S (E)｜主檔=零件清單｜鍵=項次｜篩選=項次對應的 M/S 欄同時存在 M 與 S｜輸出=新工作表 (替代料清單)
from openpyxl import load_workbook

wb = load_workbook(INPUT_PATH)
src_sheet = wb['零件清單']

# 讀取表頭 (第 1 列)
header = [cell.value for cell in src_sheet[1]]

# 用於儲存分組資訊：key=項次，value={'rows': [cell_values], 'ms_status': set()}
groups = {}

# 第一遍掃描：收集資料並判斷哪些項次有替代料 (同時擁有 M 和 S)
for row_idx in range(2, src_sheet.max_row + 1):
    row_cells = [cell.value for cell in src_sheet[row_idx]]
    item_no = row_cells[0]  # A 欄：項次
    ms_val = row_cells[4]   # E 欄：M/S

    if item_no not in groups:
        groups[item_no] = {'rows': [], 'ms_status': set()}

    groups[item_no]['rows'].append(row_cells)
    if ms_val:
        groups[item_no]['ms_status'].add(ms_val)

# 找出符合條件的項次 (同時有 M 和 S)
target_items = set()
for item_no, info in groups.items():
    if 'M' in info['ms_status'] and 'S' in info['ms_status']:
        target_items.add(item_no)

# 第二遍掃描：按原順序收集符合條件的行
output_data = []
for row_idx in range(2, src_sheet.max_row + 1):
    row_cells = [cell.value for cell in src_sheet[row_idx]]
    item_no = row_cells[0]
    if item_no in target_items:
        output_data.append(row_cells)

# 處理輸出工作表
out_sheet_name = '替代料清單'
if out_sheet_name in wb.sheetnames:
    wb.remove(wb[out_sheet_name])

dst_sheet = wb.create_sheet(out_sheet_name)

# 寫入表頭
