```python
# 推斷：資料表=系統帳、實盤（表頭第1列）｜欄位=料號、品名、數量｜主檔=系統帳｜鍵=料號｜篩選=排除小計與說明列，且兩表數量不相等｜輸出=新工作表「數量變動」
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)

def read_inventory(ws):
    # 建立欄名 -> 欄位索引（1-based）對照
    header = {}
    for cell in ws[1]:
        if cell.value is not None:
            header[cell.value] = cell.column

    col_pn = header.get("料號")
    col_name = header.get("品名")
    col_qty = header.get("數量")

    data = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        pn = row[col_pn - 1] if col_pn else None
        name = row[col_name - 1] if col_name else None
        qty = row[col_qty - 1] if col_qty else None

        # 排除小計列、說明列及空料號列
        if not pn:
            continue
        if isinstance(name, str) and ("小計" in name or name.startswith("（")):
            continue

        # 數量轉為數值
        try:
            qty = int(qty)
        except Exception:
            try:
                qty = float(qty)
            except Exception:
                qty = None

        data[pn] = {"品名": name, "數量": qty}

    return data

sys_data = read_inventory(wb["系統帳"])
act_data = read_inventory(wb["實盤"])

# 比對兩表數量，以系統帳為舊數量、實盤為新數量
diff_rows = []
for pn, sys_info in sys_data.items():
    act_info = act_data.get(pn)
    if act_info is None:
        continue
    if sys_info["數量"] != act_info["數量"]:
        diff_rows.append([
            pn,
            sys_info["品名"],
            sys_info["數量"],
            act_info["數量"],
        ])

# 建立新工作表並寫入結果
ws_out = wb.create_sheet(title="數量變動")
ws_out.append(["料號", "品名", "舊數量", "新數量"])
for row in diff_rows:
    ws_out.append(row)

wb.save(OUTPUT_PATH)
```

```python
# 推斷：資料表=舊版BOM,新版BOM（表頭第1列）｜欄位=料號,品名,數量｜主檔=舊版BOM｜鍵=料號｜篩選=數量不同｜輸出=新工作表
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
old_ws = wb['舊版BOM']
new_ws = wb['新版BOM']

# 建立舊版料號 -> (品名, 數量) 字典
old_data = {}
for row in old_ws.iter_rows(min_row=2, max_col=3, values_only=True):
    part_no, name, qty = row
    if part_no is None or name == '小計':
        break
    old_data[part_no] = (name, qty)

# 建立新版料號 -> (品名, 數量) 字典
new_data = {}
for row in new_ws.iter_rows(min_row=2, max_col=3, values_only=True):
    part_no, name, qty = row
    if part_no is None or name == '小計':
        break
    new_data[part_no] = (name, qty)

# 找出數量不同的料號
diff_items = []
for part_no, (old_name, old_qty) in old_data.items():
    if part_no in new_data:
        new_name, new_qty = new_data[part_no]
        if old_qty != new_qty:
            diff_items.append((part_no, old_name, old_qty, new_qty))

# 建立新工作表（若已存在則先刪除）
if '數量差異' in wb.sheetnames:
    del wb['數量差異']
out_ws = wb.create_sheet('數量差異')
out_ws.append(['料號', '品名', '舊數量', '新數量'])
for item in diff_items:
    out_ws.append(item)

wb.save(OUTPUT_PATH)
```
